=== .storybook/a11yExcludes.ts (full new file) ===
// Global a11y-check exclusion list (see preview.tsx). A story-level
// `parameters.a11y.context.exclude` REPLACES this array rather than extending it (Storybook's
// parameters merge is shallow) — a story under overrides/ that needs its own additional
// exclusion duplicates these same six IDs locally rather than importing across the
// .storybook/<->overrides/ boundary (a 4+ level relative import; see
// list-menu/list-menu.stories.content.ts for the one current example, which cross-references
// this file in a comment instead).
export const CHAKRA_TOAST_A11Y_EXCLUDE = [
  // Chakra UI injects toast region containers (role="region") at the root without an
  // accessible name — a known upstream limitation, framework-level not component output.
  '#chakra-toast-manager-top',
  '#chakra-toast-manager-top-right',
  '#chakra-toast-manager-top-left',
  '#chakra-toast-manager-bottom',
  '#chakra-toast-manager-bottom-right',
  '#chakra-toast-manager-bottom-left',
];

1	import React from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { Image } from '@salesforce/retail-react-app/app/components/shared/ui';
4	import { ZimmNavItem } from 'app/components/ui-kits/atoms/zimmNavItem';
5	import type { HeaderNavItemEntry } from 'app/types/contentful';
6	import { toMegaMenuItem } from './toMegaMenuItem';
7	import { MEGA_MENU_HEADING_LINK_CLASS } from './megaMenuContent.css';
8	import type { MegaMenuSection } from './types';
9	
10	const MEGA_MENU_CONTENT_RECIPE = 'ZimmMegaMenuContent';
11	
12	// Every leaf link the panel can contain (SectionColumn's ZimmNavItems) — see handlePanelKeyDown.
13	const PANEL_FOCUSABLE_SELECTOR = 'a[href], button:not([disabled])';
14	
15	/**
16	 * Up/Down arrow navigation across every leaf link in the open panel, flattened across columns
17	 * in DOM order and wrapping at either end — the simplest mental model for a multi-column mega
18	 * menu, per the confirmed design decision for this component (as opposed to a per-column
19	 * grid with Left/Right switching columns). Escape is not handled here — Chakra's Popover
20	 * already closes on Escape from anywhere within its content (`closeOnEsc`, on by default).
21	 */
22	const handlePanelKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
23	  if (e.key !== 'ArrowDown' && e.key !== 'ArrowUp') return;
24	
25	  const focusables = Array.from(e.currentTarget.querySelectorAll<HTMLElement>(PANEL_FOCUSABLE_SELECTOR));
26	  if (focusables.length === 0) return;
27	  e.preventDefault();
28	
29	  const currentIndex = focusables.indexOf(document.activeElement as HTMLElement);
30	  let nextIndex: number;
31	  if (currentIndex === -1) {
32	    nextIndex = e.key === 'ArrowDown' ? 0 : focusables.length - 1;
33	  } else {
34	    const delta = e.key === 'ArrowDown' ? 1 : -1;
35	    nextIndex = (currentIndex + delta + focusables.length) % focusables.length;
36	  }
37	  focusables[nextIndex]?.focus();
38	};
39	
40	// Leaf-link typography: Default/Navigation (12px) at tablet/desktop, h3-strong (16px) mobile.
41	const LEAF_LINK_SX = {
42	  textStyle: { base: 'heading3', md: 'navigation' },
43	};
44	
45	// A two-column item's first link (e.g. "Ready to Wear" under Collections) is styled like a
46	// heading while staying a real clickable ZimmNavItem, per Figma — not a separate `heading`
47	// field, the design intentionally makes this item both. marginBottom reproduces
48	// sectionHeading's 16px gap-to-list-below. This item also gets MEGA_MENU_HEADING_LINK_CLASS
49	// below so sectionLinks' CSS can cancel its own row gap immediately after it — see that
50	// selector's comment in megaMenuContent.css.ts.
51	const PRIMARY_LEAF_LINK_SX = {
52	  textStyle: { base: 'heading1Strong', md: 'navigation' },
53	  marginBottom: 'var(--zimm-scale-m)',
54	};
55	
56	type MegaMenuContentProps = {
57	  item: HeaderNavItemEntry;
58	  itemsKey: string;
59	  /** ZimmNavItem doesn't forward refs, so this lands on the panel container instead of the
60	   *  first leaf link (tabIndex={-1}, programmatically focusable only). */
61	  initialFocusRef?: React.Ref<HTMLDivElement>;
62	  onClose?: () => void;
63	  maxColumns?: number;
64	  /** Real popover open state, added by list-menu-popover.tsx's override — currently unused
65	   *  here (the header-shell open/close report lives in ListMenuView instead, see list-menu.tsx)
66	   *  but kept in the contract since ListMenuPopover passes it through generically. */
67	  isOpen?: boolean;
68	  /**
69	   * Whether the panel's reveal/fade animation has genuinely finished, not merely started —
70	   * distinct from `isOpen` above (true for the whole animation, not just its end). Defaults to
71	   * `true` so a story/test rendering this component standalone (no ListMenuPopover driving a
72	   * real motion phase) keeps normal tab behaviour.
73	   *
74	   * Gates every leaf link's `tabIndex` to `-1` while `false` — confirmed live against a real
75	   * browser (Storybook test-runner): Chakra's Popover flips `visibility: visible` on its
76	   * positioner the instant it opens, well before this panel's own CSS reveal (0-height,
77	   * `overflow: hidden`, `opacity: 0`) finishes — and a 0-height/overflow-hidden ancestor does
78	   * NOT reliably remove a real `<a>`/`<button>` descendant from the Tab order on its own, only
79	   * from view. Without this, Tab pressed quickly after opening could land focus on a link that
80	   * was still invisible (WCAG 2.4.7). `visibility: hidden` on the content itself was considered
81	   * and rejected — it would also suppress the fade transition it's meant to be gating, not just
82	   * remove tabbability.
83	   */
84	  isFullyOpen?: boolean;
85	};
86	
87	type SectionColumnProps = {
88	  section: MegaMenuSection;
89	  styles: Record<string, Record<string, unknown>>;
90	  onClose?: () => void;
91	  /** Two-column mega menus (e.g. Collections) style each section's first link as a heading —
92	   *  see PRIMARY_LEAF_LINK_SX above. */
93	  isTwoColumn?: boolean;
94	  /** See MegaMenuContentProps' own doc comment. */
95	  isFullyOpen: boolean;
96	};
97	
98	const SectionColumn = ({ section, styles, onClose, isTwoColumn, isFullyOpen }: SectionColumnProps) => (
99	  <chakra.div __css={styles.section}>
100	    {section.heading && <chakra.p __css={styles.sectionHeading}>{section.heading}</chakra.p>}
101	    <chakra.div __css={styles.sectionLinks}>
102	      {section.links.map((link, index) => (
103	        <ZimmNavItem
104	          key={link.href}
105	          label={link.label}
106	          href={link.href}
107	          onClick={onClose}
108	          sx={isTwoColumn && index === 0 ? PRIMARY_LEAF_LINK_SX : LEAF_LINK_SX}
109	          className={isTwoColumn && index === 0 ? MEGA_MENU_HEADING_LINK_CLASS : undefined}
110	          growUnderline
111	          tabIndex={isFullyOpen ? undefined : -1}
112	        />
113	      ))}
114	    </chakra.div>
115	  </chakra.div>
116	);
117	
118	/** Rich mega-menu popover content — renders a headerNavItem's columns plus an optional promo
119	 *  image. All Contentful-shape knowledge is isolated in `toMegaMenuItem`. */
120	export const MegaMenuContent = ({
121	  item,
122	  itemsKey,
123	  initialFocusRef,
124	  onClose,
125	  isFullyOpen = true,
126	}: MegaMenuContentProps) => {
127	  const styles = useMultiStyleConfig(MEGA_MENU_CONTENT_RECIPE);
128	  const { columns, promoImage } = toMegaMenuItem(item, itemsKey);
129	  // Only twoColumnLayout ever produces more than one column — see toMegaMenuItem.ts.
130	  const isTwoColumn = columns.length > 1;
131	
132	  return (
133	    <chakra.div ref={initialFocusRef} tabIndex={-1} __css={styles.panel} onKeyDown={handlePanelKeyDown}>
134	      <chakra.div __css={styles.sections}>
135	        {columns.map((column, columnIndex) => (
136	          <chakra.div key={`column-${columnIndex}`} __css={styles.column}>
137	            {column.map((section, index) => (
138	              <SectionColumn
139	                key={`section-${index}`}
140	                section={section}
141	                styles={styles}
142	                onClose={onClose}
143	                isTwoColumn={isTwoColumn}
144	                isFullyOpen={isFullyOpen}
145	              />
146	            ))}
147	          </chakra.div>
148	        ))}
149	      </chakra.div>
150	      {promoImage && (
151	        <chakra.div __css={styles.promoImageWrapper}>
152	          <Image src={promoImage.src} alt={promoImage.alt} loading="lazy" __css={styles.promoImage} />
153	        </chakra.div>
154	      )}
155	    </chakra.div>
156	  );
157	};
158	
159	MegaMenuContent.displayName = 'MegaMenuContent';
160

1	/**
2	 * Presentational shapes `megaMenuContent` renders. `toMegaMenuItem.ts` is the only place that
3	 * maps a raw `headerNavItem` Contentful entry into these — if the content model changes, only
4	 * that adapter needs to change, not this component or its recipe.
5	 */
6	
7	export type MegaMenuLink = {
8	  label: string;
9	  href: string;
10	};
11	
12	export type MegaMenuSection = {
13	  /** Omitted for an unheaded curated group (e.g. "New"'s groups) — see toMegaMenuItem.ts. */
14	  heading?: string;
15	  links: MegaMenuLink[];
16	};
17	
18	export type MegaMenuItem = {
19	  /** Each element is one visual side-by-side column; sections within a column stack
20	   *  vertically. See toMegaMenuItem.ts for the default-vs-twoColumnLayout split. */
21	  columns: MegaMenuSection[][];
22	  promoImage?: {
23	    src: string;
24	    alt: string;
25	  };
26	};
27

1	import React, { useEffect, useRef } from 'react';
2	import {
3	  Box,
4	  Center,
5	  Drawer,
6	  DrawerBody,
7	  DrawerContent,
8	  DrawerOverlay,
9	  Image,
10	  Spinner,
11	  Text,
12	  useMultiStyleConfig,
13	} from '@salesforce/retail-react-app/app/components/shared/ui';
14	import { useCustomerType } from '@salesforce/commerce-sdk-react';
15	import { noop } from '@salesforce/retail-react-app/app/utils/utils';
16	import { DRAWER_BODY_SX, DRAWER_CONTENT_SX, DRAWER_OVERLAY_SX } from './drawer-menu.css';
17	import { ZimmNavItem } from 'app/components/ui-kits/atoms/zimmNavItem';
18	import { useUiCopy } from 'app/hooks/useUiCopy';
19	import { useHeaderNav } from 'app/hooks/useHeaderNav';
20	import { useDrawerMenuState } from 'app/hooks/useDrawerMenuState';
21	import { resolveImageEntry } from 'app/utils/resolveImageEntry';
22	import type { HeaderNavItemEntry, NavGroupEntry } from 'app/types/contentful';
23	
24	const SIGN_IN_HREF = '/login';
25	const WISHLIST_HREF = '/account/wishlist';
26	const ACCOUNT_HREF = '/account';
27	
28	// A two-column item's first link per group is styled like a heading while staying a real
29	// clickable ZimmNavItem (see megaMenuContent/index.tsx's PRIMARY_LEAF_LINK_SX for the
30	// desktop/tablet equivalent). marginBottom tops l2LinkList's 12px gap up to Figma's 24px for
31	// this one pair, rather than changing the list's gap for every item.
32	const L2_PRIMARY_LINK_SX = {
33	  textStyle: 'heading1Strong',
34	  marginBottom: 'var(--zimm-scale-s)',
35	};
36	const L2_LEAF_LINK_SX = { textStyle: 'heading3' };
37	
38	type DrawerMenuViewProps = {
39	  isOpen: boolean;
40	  onClose: () => void;
41	  onLogoClick?: () => void;
42	  /** Region-resolved header nav items, or undefined while loading (see useHeaderNav.ts). */
43	  items: ReadonlyArray<HeaderNavItemEntry> | undefined;
44	  isLoading: boolean;
45	  /** The L1 item currently drilled into — renders the L2 panel when set. */
46	  activeItem: HeaderNavItemEntry | null;
47	  isDrilledIn: boolean;
48	  /** Called when the shopper taps an L1 row that has columns. */
49	  onDrillInto: (item: HeaderNavItemEntry) => void;
50	};
51	
52	/** L1 root nav list — a direct-link item renders as a ZimmNavItem link; an item with columns
53	 *  renders as a button that drills to L2. No chevron — Figma renders every row as plain text. */
54	const DrawerMenuL1Nav = ({
55	  items,
56	  onDrillInto,
57	  styles,
58	}: {
59	  items: ReadonlyArray<HeaderNavItemEntry>;
60	  onDrillInto: (item: HeaderNavItemEntry) => void;
61	  styles: Record<string, Record<string, unknown>>;
62	}) => (
63	  <Box as="ul" {...styles.l1List} listStyleType="none">
64	    {items.map((item) => {
65	      const { label, href, columns = [] } = item.fields;
66	      const hasColumns = columns.length > 0;
67	
68	      return (
69	        <Box as="li" key={item.sys.id} {...styles.l1Row}>
70	          {hasColumns ? (
71	            <ZimmNavItem label={label} onClick={() => onDrillInto(item)} sx={{ textStyle: 'heading1Strong' }} />
72	          ) : (
73	            <ZimmNavItem label={label} href={href} sx={{ textStyle: 'heading1Strong' }} />
74	          )}
75	        </Box>
76	      );
77	    })}
78	  </Box>
79	);
80	
81	/** L2 drilled-in panel — every column's heading (optional) + links, flattened into one stacked
82	 *  list (mobile stacks columns vertically, unlike desktop/tablet's side-by-side layout).
83	 *
84	 *  No Figma motion spec exists for the L1<->L2 transition, so this swap is instant — a
85	 *  deliberate placeholder pending a real transition. */
86	const DrawerMenuL2Nav = ({
87	  activeItem,
88	  styles,
89	}: {
90	  activeItem: HeaderNavItemEntry;
91	  styles: Record<string, Record<string, unknown>>;
92	}) => {
93	  const isTwoColumn = Boolean(activeItem.fields.twoColumnLayout);
94	
95	  return (
96	    <Box>
97	      {(activeItem.fields.columns ?? []).map((group: NavGroupEntry) => (
98	        <Box key={group.sys.id}>
99	          {group.fields.heading && (
100	            <Text as="h2" textStyle="heading1Strong" {...styles.l2Heading}>
101	              {group.fields.heading}
102	            </Text>
103	          )}
104	          <Box as="ul" {...styles.l2LinkList} listStyleType="none">
105	            {group.fields.links.map((link, index) => (
106	              <Box as="li" key={link.sys.id}>
107	                <ZimmNavItem
108	                  label={link.fields.label}
109	                  href={link.fields.href}
110	                  sx={isTwoColumn && index === 0 ? L2_PRIMARY_LINK_SX : L2_LEAF_LINK_SX}
111	                />
112	              </Box>
113	            ))}
114	          </Box>
115	        </Box>
116	      ))}
117	    </Box>
118	  );
119	};
120	
121	/** Header desktop-nav's mobile counterpart — presentational; receives resolved nav items and
122	 *  L1/L2 drill state as props, matching the ListMenuView/ListMenu split. `DrawerMenu` below is
123	 *  this component's container.
124	 *
125	 *  Full-screen takeover, not a slide-in panel: still a Chakra `<Drawer>` for its focus-trap/
126	 *  Escape/portal behaviour, but the co-located recipe renders it full-bleed below the header.
127	 *  The header shell's LeftBar/RightBar already own the Exit/search/bag row at this depth, so no
128	 *  header markup is duplicated here.
129	 *
130	 * @param props see DrawerMenuViewProps
131	 */
132	export const DrawerMenuView = ({
133	  isOpen,
134	  onClose,
135	  onLogoClick: _onLogoClick = noop,
136	  items,
137	  isLoading,
138	  activeItem,
139	  isDrilledIn,
140	  onDrillInto,
141	}: DrawerMenuViewProps) => {
142	  const { t } = useUiCopy();
143	  const { isRegistered } = useCustomerType();
144	  const styles = useMultiStyleConfig('ZimmDrawerMenu') as unknown as Record<string, Record<string, unknown>>;
145	
146	  // L1<->L2 is a depth swap, not a route change, so nothing else moves focus when one panel
147	  // unmounts and the other takes its place — without this, focus silently drops to
148	  // document.body and keyboard users restart tabbing from the top of the drawer every time they
149	  // drill in or back out. Also gives aria-live's announcement a stable, focused target.
150	  const panelRef = useRef<HTMLDivElement>(null);
151	  // Mirrors the render guard below exactly: neither panel is mounted (panelRef.current is
152	  // still null) until loading finishes and items resolves, so this has to be in the effect's
153	  // own condition/deps — otherwise the nav-open case (isOpen/isDrilledIn/activeItem all already
154	  // settled before the fetch completes) never re-runs the effect once the panel actually mounts.
155	  const panelReady = !isLoading && items !== undefined;
156	  useEffect(() => {
157	    if (isOpen && panelReady) panelRef.current?.focus();
158	  }, [isOpen, isDrilledIn, activeItem, panelReady]);
159	
160	  const promoImage = isDrilledIn ? resolveImageEntry(activeItem?.fields.promoImage) : undefined;
161	
162	  return (
163	    <Drawer isOpen={isOpen} onClose={onClose} placement="left" size="full">
164	      <DrawerOverlay {...DRAWER_OVERLAY_SX}>
165	        <DrawerContent aria-label={t('drawer_menu.header.assistive_msg.title', 'Menu Drawer')} {...DRAWER_CONTENT_SX}>
166	          {/* padding={0}: real spacing lives on navGroup below — DrawerBody's own padding
167	              didn't reliably apply via Modal's internal style merge. DRAWER_BODY_SX makes
168	              DrawerBody the flex column navGroup/the L2 image sit in as siblings. */}
169	          <DrawerBody padding={0} {...DRAWER_BODY_SX}>
170	            <Box {...styles.navGroup}>
171	              {/* aria-live/aria-atomic deliberately do NOT wrap this whole div — an L1<->L2
172	                  drill is a full-panel swap (unlike desktop's always-mounted mega-menu content),
173	                  so an atomic live region here would re-announce every link in the new panel on
174	                  top of the correct, already-in-place announcement: the focus effect below moves
175	                  focus onto the new panel (aria-label={activeItem.fields.label} for L2), which a
176	                  screen reader announces on its own via the focus change. Same root cause and
177	                  fix as list-menu.tsx's own aria-live scoping — see that file's comment. */}
178	              <div id="drawer-menu-nav" aria-busy={isLoading}>
179	                {isLoading || items === undefined ? (
180	                  <Center p="8" aria-live="polite" aria-atomic="true">
181	                    <Spinner size="xl" />
182	                  </Center>
183	                ) : isDrilledIn && activeItem ? (
184	                  <Box ref={panelRef} tabIndex={-1} aria-label={activeItem.fields.label}>
185	                    <DrawerMenuL2Nav activeItem={activeItem} styles={styles} />
186	                  </Box>
187	                ) : (
188	                  <Box ref={panelRef} tabIndex={-1}>
189	                    <DrawerMenuL1Nav items={items} onDrillInto={onDrillInto} styles={styles} />
190	                  </Box>
191	                )}
192	              </div>
193	
194	              {/* L2 hides the wishlist/account footer — back returns to the full L1 list. */}
195	              {!isDrilledIn && (
196	                <Box {...styles.footer}>
197	                  <ZimmNavItem
198	                    label={t('drawer_menu.link.wishlist', 'Wishlist')}
199	                    href={WISHLIST_HREF}
200	                    sx={{ textStyle: 'body2' }}
201	                  />
202	                  {isRegistered ? (
203	                    <ZimmNavItem
204	                      label={t('drawer_menu.link.account', 'Account')}
205	                      href={ACCOUNT_HREF}
206	                      sx={{ textStyle: 'body2' }}
207	                    />
208	                  ) : (
209	                    <ZimmNavItem
210	                      label={t('drawer_menu.link.sign_in', 'Sign In')}
211	                      href={SIGN_IN_HREF}
212	                      sx={{ textStyle: 'body2' }}
213	                    />
214	                  )}
215	                </Box>
216	              )}
217	            </Box>
218	
219	            {/* Sibling of navGroup, not nested inside it, so it stays full-bleed instead of
220	                inheriting navGroup's own paddingLeft. */}
221	            {promoImage && (
222	              <Box {...styles.l2ImageWrapper}>
223	                <Image src={promoImage.src} alt={promoImage.alt} loading="lazy" __css={styles.l2Image} />
224	              </Box>
225	            )}
