41	  const sections = sectionsField.map(toSection);
42	
43	  // Default: every group stacks in one shared column (confirmed via Figma's "New" frame).
44	  // twoColumnLayout splits them into two side-by-side columns instead — an explicit editorial
45	  // flag rather than inferring column count from heading presence or group count. Guarded by
46	  // sections.length > 1: a single-section group with twoColumnLayout set would otherwise split
47	  // into [[section], []] — a real column with content plus an empty one that still renders
48	  // (and still gets two-column link styling applied to the only section present).
49	  const columns = itemFields.twoColumnLayout && sections.length > 1 ? splitEvenly(sections, 2) : [sections];
50	
51	  const promoImage = resolveImageEntry(item.fields.promoImage);
52	
53	  return { columns, promoImage };
54	};
55	
56	/** Splits `items` into `columnCount` columns as evenly as possible, preserving order — the
57	 *  first column gets the larger half when the count is odd. */
58	const splitEvenly = <T>(items: T[], columnCount: number): T[][] => {
59	  const perColumn = Math.ceil(items.length / columnCount);
60	  return Array.from({ length: columnCount }, (_, i) => items.slice(i * perColumn, (i + 1) * perColumn));
61	};
