60	  contentComponent?: React.ElementType;
61	  item?: HeaderNavItemEntry;
62	  name?: string;
63	  itemsKey?: string;
64	  maxColumns?: number;
65	  /**
66	   * Controlled by ListMenuView (a single source of truth shared across every sibling
67	   * ListMenuPopover) rather than each instance owning its own useDisclosure() — necessary for
68	   * mutual exclusion, since this override's `closeOnBlur={false}` means nothing else closes an
69	   * already-open item.
70	   *
71	   * True for *both* the outgoing item and the incoming one during a switch, not just the
72	   * active one — see `isActiveItem` below for why.
73	   */
74	  isOpen: boolean;
75	  onOpen: () => void;
76	  onClose: () => void;
77	  /**
78	   * Whether THIS item is the one useMegaMenuMotion considers *active* (not merely pending) —
79	   * distinct from `isOpen` above. During a switch, the pending (incoming) item is `isOpen` but
80	   * not yet `isActiveItem`: its Popover mounts/positions early, while the outgoing item's
81	   * content still covers the page, so there's no positioning left to do once it actually takes
82	   * over — without this, a real flash-of-page-content gap appeared between the outgoing
83	   * Popover closing and the incoming one finishing its own first-open positioning. The pending
84	   * item's own CSS phase stays 'closed' throughout — only its Popover mount state moves early.
85	   */
86	  isActiveItem?: boolean;
87	  /**
88	   * Whether THIS item's L1 trigger should show as active/underlined — the most recently
89	   * *hovered* item, which changes instantly. Distinct from `isOpen`/`isActiveItem` above (which
90	   * stay true for the outgoing item throughout a switch's fade-out) so both triggers' underlines
91	   * animate concurrently instead of the outgoing one waiting for the switch to finish.
92	   */
93	  isTriggerActive?: boolean;
94	  /** The shared mega-menu motion phase — only meaningful for the instance where `isActiveItem`
