107	// Override of base list-menu-popover.jsx: content is always rendered (Chakra's Popover hides
108	// closed content on its own — an a11y improvement over gating with `{isOpen && ...}`).
109	// closeOnBlur={false} + no onMouseLeave: the menu only closes via the Close control, a leaf
110	// link, or Escape. Imports our own list-menu-trigger.tsx override instead of base.
111	const ListMenuPopover = ({
112	  contentComponent,
113	  item,
114	  name,
115	  itemsKey,
116	  maxColumns,
117	  isOpen,
118	  onOpen,
119	  onClose,
120	  isActiveItem,
121	  isTriggerActive,
122	  motionPhase,
123	  onExpandComplete,
124	  onContentInComplete,
125	  onContentOutComplete,
126	  onCollapseComplete,
127	  triggerRef,
128	  onTriggerKeyDown,
129	}: ListMenuPopoverProps) => {
130	  const initialFocusRef = useRef<HTMLElement>(null);
131	  const ContentComponent = contentComponent || ListMenuContent;
132	  const theme = useTheme() as { components: Record<string, { baseStyle: Record<string, Record<string, unknown>> }> };
133	  const { baseStyle } = theme.components.ListMenu;
134	  const { t } = useUiCopy();
135	
136	  // A pending (isOpen yet not-yet-active) instance must stay at the 'closed' resting state —
137	  // every completion callback below is guarded by an exact phase match, so a spurious
138	  // transitionend on a non-active instance can never fire one of them.
139	  const phase: MegaMenuMotionPhase = isActiveItem ? motionPhase ?? 'closed' : 'closed';
140	  const gridTemplateRowsTarget = isPanelExpanded(phase) ? '1fr' : '0fr';
141	  const gridTemplateRows = useTransitionSafeValue(gridTemplateRowsTarget, isPanelHeightAnimating(phase), '0fr');
142	
143	  // Per the W3C WAI-ARIA APG's Disclosure Navigation Menu pattern (the canonical reference for
144	  // this exact "top-level link that also opens a dropdown" shape — confirmed against
145	  // https://www.w3.org/WAI/ARIA/apg/patterns/disclosure/examples/disclosure-navigation/'s own
146	  // keyboard-support table): opening the menu leaves focus on the trigger — it does NOT jump
147	  // into the panel — and Down Arrow (list-menu-trigger.tsx's onEnterPanel) is the documented
148	  // fast-path a keyboard user takes from there into the panel's first link. Tab still flows
149	  // through the open panel's own links afterwards, same as any other revealed content in normal
150	  // document order — nothing here needs to intercept Tab. `autoFocus={false}` below exists only
151	  // to stop Chakra's own default (which would otherwise move focus into the panel the instant
152	  // isOpen flips true, for every open method including a mouse hover) from fighting this.
153	  const focusFirstPanelLink = () => {
154	    initialFocusRef.current?.querySelector<HTMLElement>(PANEL_FOCUSABLE_SELECTOR)?.focus();
155	  };
156	
157	  // Down Arrow can be pressed the instant the panel opens, before its reveal/fade animation has
158	  // actually finished (confirmed live against a real browser: fast keyboard input landed focus
159	  // on a link that was still 0-height/opacity-0 — the same WCAG 2.4.7 bug the old auto-focus-on-
160	  // open behaviour had, just reachable through this new path instead). If the panel is already
161	  // fully open, focus moves immediately; otherwise the request is remembered and fulfilled once
162	  // phase actually reaches 'open', not merely 'contentIn' (opacity is still ramping up then —
163	  // see isContentVisible's own comment; only 'open' means the transition has genuinely settled).
164	  const pendingEnterPanelRef = useRef(false);
165	  const onEnterPanel = () => {
166	    if (phase === 'open') {
167	      focusFirstPanelLink();
168	    } else {
169	      pendingEnterPanelRef.current = true;
170	    }
171	  };
172	  useEffect(() => {
173	    // A Down Arrow press can be followed by the menu closing (or switching to a different item)
174	    // before the panel ever reaches 'open' — without this, the stale request would fire later
175	    // when this item re-opens via a plain pointer hover, moving focus with no new keyboard input.
176	    // isOpen must be a dependency, not just phase: a pending (isOpen yet not-yet-active) instance
177	    // has phase permanently stuck at 'closed' (see the `phase` derivation above), so isOpen
178	    // flipping false on its own would never otherwise re-run this effect to clear the ref.
179	    if (!isOpen || phase === 'closed') {
180	      pendingEnterPanelRef.current = false;
181	      return;
182	    }
183	    if (phase === 'open' && pendingEnterPanelRef.current) {
184	      pendingEnterPanelRef.current = false;
185	      focusFirstPanelLink();
186	    }
187	  }, [isOpen, phase]);
188	
189	  return (
190	    <Box>
191	      <Popover
192	        placement="bottom-start"
193	        initialFocusRef={initialFocusRef}
194	        // Chakra Popover's own focus-management toggle, not the native HTML autofocus attribute
195	        // jsx-a11y/no-autofocus exists to catch — disabled deliberately: Chakra's autoFocus
196	        // would move focus into the panel the instant isOpen flips true, for every open method
197	        // including a mouse hover, which the Disclosure Navigation pattern comment above this
198	        // component explicitly does not want. Focus stays on the trigger; see that comment.
199	        // eslint-disable-next-line jsx-a11y/no-autofocus
200	        autoFocus={false}
201	        onOpen={onOpen}
202	        onClose={onClose}
203	        isOpen={isOpen}
204	        variant="fullWidth"
205	        closeOnBlur={false}
206	      >
207	        <Fragment>
208	          <ListMenuTrigger
209	            item={item}
210	            name={name}
211	            isActive={isTriggerActive}
212	            onOpen={onOpen}
213	            onClose={onClose}
214	            // Only wired while actually open — ArrowDown on the trigger is a no-op while closed
215	            // (Space/Enter/click remain the only way to open it). Gating here, not just inside
216	            // onEnterPanel itself, matters: without it, an ArrowDown press on a closed trigger
217	            // could arm the pending-focus flag above and then fire later if the menu happens to
218	            // open via some other means (e.g. a hover) — this way it's a true no-op instead.
219	            onEnterPanel={isOpen ? onEnterPanel : undefined}
220	            triggerRef={triggerRef}
221	            onTriggerKeyDown={onTriggerKeyDown}
222	          />
223	          {/* Focus-return-on-close (Chakra's own useFocusOnHide, trigger="click" default) needs
224	              this same ref — Popover clones it onto ListMenuTrigger's element internally via
225	              PopoverTrigger, so no separate wiring is needed here for that half. */}
226	          <PopoverContent
227	            data-testid="popover-menu"
228	            aria-label={t('list_menu.popover.assistive_msg.dialog_name', '{name} menu', { name: name ?? '' })}
229	            {...baseStyle.popoverContent}
230	          >
231	            <PopoverBody {...baseStyle.popoverBody}>
232	              {/* grid-template-rows 0fr<->1fr — animates to/from an unknown height with no JS
233	                  measurement, works for both desktop's fixed and tablet's fluid promo image. */}
234	              <Box
235	                data-testid="panel-reveal"
236	                {...baseStyle.panelRevealWrapper}
237	                sx={{
238	                  gridTemplateRows,
239	                  transition: isPanelHeightAnimating(phase)
240	                    ? 'grid-template-rows var(--zimm-motion-duration-default) ease-in'
241	                    : 'none',
242	                }}
243	                onTransitionEnd={(e: React.TransitionEvent<HTMLDivElement>) => {
244	                  if (e.target !== e.currentTarget) return;
245	                  if (phase === 'expanding') onExpandComplete?.();
246	                  if (phase === 'collapsing') onCollapseComplete?.();
247	                }}
248	              >
249	                <Box {...baseStyle.panelRevealInner}>
250	                  <Box
251	                    data-testid="panel-content-fade"
252	                    sx={{
253	                      opacity: isContentVisible(phase) ? 1 : 0,
254	                      transition: 'opacity var(--zimm-motion-duration-fast) var(--zimm-motion-easing-fades)',
255	                    }}
256	                    onTransitionEnd={(e: React.TransitionEvent<HTMLDivElement>) => {
257	                      if (e.target !== e.currentTarget) return;
258	                      if (phase === 'contentIn') onContentInComplete?.();
259	                      if (phase === 'contentOut') onContentOutComplete?.();
260	                    }}
261	                  >
262	                    <ContentComponent
263	                      item={item}
264	                      itemsKey={itemsKey}
265	                      initialFocusRef={initialFocusRef}
266	                      onClose={onClose}
267	                      maxColumns={maxColumns}
268	                      isOpen={isOpen}
269	                      isFullyOpen={phase === 'open'}
270	                    />
271	                  </Box>
272	                </Box>
273	              </Box>
274	            </PopoverBody>
275	          </PopoverContent>
276	        </Fragment>
277	      </Popover>
278	    </Box>
279	  );
280	};
281	
282	export { ListMenuPopover };
