1	import React from 'react';
2	import { useMergeRefs } from '@chakra-ui/react';
3	import { PopoverTrigger } from '@salesforce/retail-react-app/app/components/shared/ui';
4	import { ZimmNavItem } from 'app/components/ui-kits/atoms/zimmNavItem';
5	import type { HeaderNavItemEntry } from 'app/types/contentful';
6	import type { HeaderNavTriggerElement } from 'app/hooks/useHeaderNavKeyboard';
7	
8	type ListMenuTriggerProps = {
9	  /** A mega-menu trigger item (one with columns) often has no `href` of its own, rendering as a
10	   *  real `<button>` — but at least one real item ("New") carries both a real `href` AND
11	   *  columns, rendering as a real `<a>` instead (see ZimmNavItem's own href branch). That matters
12	   *  for keyboard support below: a native `<a>` only activates on Enter/click, never Space, so
13	   *  Space needs its own explicit handling for this case — see the onKeyDown handler below. */
14	  item?: Pick<HeaderNavItemEntry, 'fields'>;
15	  name?: string;
16	  /**
17	   * Drives ZimmNavItem's `visuallyActive` (underlined, no aria-current) state — deliberately
18	   * not named `isOpen`: it's whichever item was most recently hovered, changing the instant a
19	   * new L1 item is hovered. Using ListMenuPopover's own `isOpen` here (true for both outgoing
20	   * and incoming item during a switch) would leave the outgoing trigger's underline visible
21	   * until the whole switch finished, instead of both underlines animating concurrently.
22	   * `visuallyActive`, not `active`/aria-current: this reflects "the mega-menu is open," not a
23	   * real current-page state, and announcing aria-current="page" for a merely-hovered item would
24	   * tell screen-reader users they've navigated somewhere they haven't.
25	   */
26	  isActive?: boolean;
27	  onOpen?: () => void;
28	  onClose?: () => void;
29	  /** Down Arrow's fast-path into the panel's first link, per the W3C WAI-ARIA APG's Disclosure
30	   *  Navigation Menu pattern — only passed (non-undefined) while this item's panel is actually
31	   *  open; see list-menu-popover.tsx. Opening itself never moves focus off this trigger. */
32	  onEnterPanel?: () => void;
33	  /** Merged onto the trigger element alongside Chakra's own PopoverTrigger-injected ref — see
34	   *  useHeaderNavKeyboard.ts. Targets the real `<a>`/`<button>` node, not a wrapping `<Box>`. */
35	  triggerRef?: React.Ref<HeaderNavTriggerElement>;
36	  /** Left/Right/Home/End roving focus across L1 triggers — see useHeaderNavKeyboard.ts. */
37	  onTriggerKeyDown?: (event: React.KeyboardEvent) => void;
38	};
39	
40	const ListMenuTrigger = ({
41	  item,
42	  name,
43	  isActive,
44	  onOpen,
45	  onClose,
46	  onEnterPanel,
47	  triggerRef,
48	  onTriggerKeyDown,
49	}: ListMenuTriggerProps) => {
50	  // Chakra's PopoverTrigger clones its own aria-haspopup/aria-expanded/aria-controls/onClick/ref
51	  // onto whatever single child it wraps (confirmed against @chakra-ui/popover's use-popover.ts)
52	  // — that child must be this label itself, not a decorative icon, or the visible, correctly-
53	  // labelled control never gets the state a screen reader needs (see this file's git history:
54	  // an earlier revision kept a separate zero-width "chevron" button around specifically to hold
55	  // that wiring, which put the real name on one element and the real state on an invisible one —
56	  // a WCAG 4.1.2 Name/Role/Value violation, plus a keyboard-only, no-focus-ring extra Tab stop
57	  // between every pair of L1 items).
58	  const mergedRef = useMergeRefs(triggerRef);
59	
60	  return (
61	    <PopoverTrigger>
62	      <ZimmNavItem
63	        ref={mergedRef}
64	        label={name ?? ''}
65	        href={item?.fields.href}
66	        visuallyActive={isActive}
67	        growUnderline
68	        // Pointer hover still opens the menu — PopoverTrigger's own injected onClick (below)
69	        // only covers click/Enter/Space activation.
70	        onMouseOver={onOpen}
71	        onKeyDown={(e) => {
72	          if (e.key === 'Escape') onClose?.();
73	          // Regression fix: a real <a> (an item that carries both an href and columns, e.g.
74	          // "New") never activates on Space — only Enter/click do, and both of those already
75	          // navigate via the real href, which is correct there. Space is this trigger's own
76	          // "open the menu" key everywhere else (a plain <button> gets it for free via native
77	          // activation), so it needs wiring by hand for the link case specifically — opening
78	          // only, matching what Space is asked to do (not a full open/close toggle).
79	          else if (e.key === ' ' && item?.fields.href) {
80	            e.preventDefault();
81	            onOpen?.();
82	          }
83	          // Down Arrow's fast-path into the open panel's first link — see onEnterPanel's own
84	          // doc comment. A no-op key when the panel isn't open (onEnterPanel is undefined then).
85	          else if (e.key === 'ArrowDown' && onEnterPanel) {
86	            e.preventDefault();
87	            onEnterPanel();
88	          }
89	          onTriggerKeyDown?.(e);
90	        }}
91	      />
92	    </PopoverTrigger>
93	  );
94	};
95	
96	export { ListMenuTrigger };
